import numpy as np

# Safe prediction function that handles corrupted images
def safe_predict(model, generator):
    features_list = []
    batch_count = 0

    for i, (x_batch, y_batch) in enumerate(generator):
        try:
            batch_features = model.predict(x_batch, verbose=0)
            features_list.append(batch_features)
            batch_count += 1
        except Exception as e:
            print(f"Skipping batch {i} due to error: {e}")
            continue

    # Concatenate all successful batches
    if features_list:
        return np.concatenate(features_list, axis=0)
    else:
        print("Warning: No valid batches were processed")
        return np.array([])

